html:
{#- Laid out like the workflow folder's "6. Final Interview / Interview Assessment Form" (Admin, Faculty, Research): one panellist's form for one candidate. -#}
{%- set iv = frappe.db.get_value("Interview", doc.interview, ["scheduled_datetime", "application"], as_dict=True) if doc.interview else None -%}
{%- set app = frappe.db.get_value("Application", doc.application or (iv and iv.application), ["application_id", "job_opening"], as_dict=True) if (doc.application or (iv and iv.application)) else None -%}
{%- set track = frappe.db.get_value("Job Opening", app.job_opening, "track") if app else None -%}
{%- set rubric = frappe.db.get_value("Scoring Rubric Template", {"track": track, "stage": "Final Interview", "is_active": 1}, ["name", "pass_threshold_percent"], as_dict=True) if track else None -%}
{%- set guidance = frappe.get_all("Scoring Criterion Row", filters={"parent": rubric.name, "parenttype": "Scoring Rubric Template"}, fields=["criterion_label", "guidance_text"]) if rubric else [] -%}
{%- set notes = {
	"Admin": "This scoresheet will serve as an Interview Assessment Form for all non-teaching staff recruitment",
	"Faculty": "This scoresheet will serve as an Interview Assessment Form for all Teaching Staff recruitment, irrespective of levels",
	"Research": "This scoresheet will serve as an Interview Assessment Form for all research staff recruitment",
} -%}
{%- set pass_percent = (rubric.pass_threshold_percent if rubric and rubric.pass_threshold_percent else 50) -%}
{%- set ask_area = track in ("Admin", "Faculty") -%}
<style>
	.ia { font-family: Arial, sans-serif; font-size: 11px; color: #111; }
	.ia h1 { font-size: 15px; text-align: center; margin: 0 0 4px; }
	.ia h2 { font-size: 12px; text-align: center; margin: 0 0 8px; letter-spacing: .5px; }
	.ia ul { margin: 0 0 8px 16px; padding: 0; }
	.ia table { width: 100%; border-collapse: collapse; }
	.ia td, .ia th { border: 1px solid #555; padding: 5px 6px; vertical-align: top; }
	.ia th { background: #f2e6e8; text-align: center; font-weight: bold; }
	.ia .q { font-weight: normal; font-size: 9px; color: #333; text-align: left; }
	.ia .num { text-align: center; }
	.ia .muted { color: #666; font-size: 9px; }
	.ia .foot td { height: 28px; }
	.ia .sig { max-height: 60px; max-width: 220px; }
</style>
{{ pathways_letterhead(doc) }}
<div class="ia">

	<h2>{{ (doc.job_title or "") | upper }} | RECRUITMENT | INTERVIEW ASSESSMENT FORM</h2>
	<ul>
		<li>{{ notes.get(track) or notes["Admin"] }}</li>
		<li>This scoresheet is to be completed by each member of the Selection Committee</li>
		<li>To be eligible for an offer, a candidate requires a minimum score of {{ "%g" % frappe.utils.flt(pass_percent) }}% of the total marks</li>
		<li>Whenever possible, please ensure that there is a waitlist recommended</li>
	</ul>
	<table style="margin-bottom:8px">
		<tr>
			<td style="width:50%"><b>PANELIST NAME:</b> {{ frappe.get_fullname(doc.panelist) if doc.panelist else "" }}</td>
			<td><b>POSITION:</b> {{ doc.job_title or "" }}</td>
		</tr>
		<tr>
			<td></td>
			<td><b>DATE:</b> {{ frappe.utils.formatdate(iv.scheduled_datetime, "dd MMM yyyy") if iv and iv.scheduled_datetime else "" }}
				&nbsp;&nbsp;&nbsp; <b>TIME:</b> {{ frappe.utils.format_datetime(iv.scheduled_datetime, "h:mm a") if iv and iv.scheduled_datetime else "" }}</td>
		</tr>
	</table>
	<table>
		<tr>
			<th style="width:4%">SL NO</th>
			<th style="width:15%">CANDIDATE NAME</th>
			{% if ask_area %}<th style="width:12%">AREA OF SPECIALIZATION</th>{% endif %}
			{% for c in doc.criteria %}
			<th>{{ loop.index }}. {{ (c.criterion_label or "") | upper }}<br>(MAX SCORE = {{ "%g" % frappe.utils.flt(c.max_score) }})
				{% for g in guidance if g.criterion_label == c.criterion_label and g.guidance_text %}<div class="q">{{ g.guidance_text }}</div>{% endfor %}</th>
			{% endfor %}
			<th style="width:9%">TOTAL SCORE<br>({% for c in doc.criteria %}{{ loop.index }}{% if not loop.last %} + {% endif %}{% endfor %})<br>(MAX SCORE = {{ "%g" % frappe.utils.flt(doc.max_score) }})</th>
			<th style="width:20%">ADDITIONAL COMMENTS</th>
		</tr>
		<tr>
			<td class="num">1</td>
			<td>{{ doc.candidate_name or "" }}{% if app %}<div class="muted">{{ app.application_id or "" }}</div>{% endif %}</td>
			{% if ask_area %}<td>{{ doc.area_of_specialization or "" }}</td>{% endif %}
			{% for c in doc.criteria %}<td class="num">{{ "%g" % frappe.utils.flt(c.score_given) if c.score_given is not none else "" }}</td>{% endfor %}
			<td class="num"><b>{{ "%g" % frappe.utils.flt(doc.total_score) }}</b>{% if doc.score_percent %}<div class="muted">{{ "%g" % frappe.utils.flt(doc.score_percent, 1) }}%</div>{% endif %}</td>
			<td>{{ (doc.recommendation or "") | e | replace("\n", "<br>") }}</td>
		</tr>
	</table>
	<table class="foot" style="margin-top:8px">
		<tr>
			<td style="width:24%"><b>Recommendation of the Panelist:</b></td>
			<td>{{ doc.verdict or "" }}</td>
		</tr>
		<tr>
			<td><b>Signature of Panelist:</b></td>
			<td>
				{%- set signature = doc.get("panelist_signature") or "" -%}
				{#- An empty Signature field prints as Frappe's placeholder image: treat it as unsigned. -#}
				{%- if signature and "signature-placeholder" not in signature -%}
				<img class="sig" src="{{ signature }}" alt="Signature">
				{%- elif doc.panelist_signature_confirmed -%}
				Confirmed on the recruitment platform by {{ frappe.get_fullname(doc.panelist) if doc.panelist else "the panellist" }}{% if doc.entered_by and doc.entered_by != doc.panelist %} (entered by {{ frappe.get_fullname(doc.entered_by) }}){% endif %}, {{ frappe.utils.format_datetime(doc.modified, "dd MMM yyyy, h:mm a") }}
				{%- endif -%}
			</td>
		</tr>
	</table>
</div>
